//! 🪡️ Scalar input owners move into cloned native Part21 slots without a whole-instance value projection.
use super::*;
fn input_text(value:&mut DslValue)->Option<String>{if !matches!(value,DslValue::String(_)){return None;}let DslValue::String(text)=std::mem::replace(value,DslValue::Null)else{unreachable!()};Some(text)}
fn decimal(value:&mut DslValue)->Result<Option<Part21Decimal>,Fault>{let DslValue::Object(fields)=value else{return Ok(None)};if !(3..=4).contains(&fields.len()){return Ok(None);}let mut negative=None;let mut coefficient=None;let mut scale=None;let mut exponent=None;for(index,(key,value))in fields.iter().enumerate(){match key.as_str(){"negative"if negative.is_none()=>{negative=value.as_bool();if negative.is_none(){return Ok(None);}},"coefficient"if coefficient.is_none()&&matches!(value,DslValue::String(_))=>coefficient=Some(index),"scale"if scale.is_none()=>{scale=value.as_u64().and_then(|value|u32::try_from(value).ok());if scale.is_none(){return Ok(None);}},"exponent"if exponent.is_none()=>exponent=Some(if matches!(value,DslValue::Null){None}else{Some(value.as_i64().and_then(|value|i32::try_from(value).ok()).ok_or_else(||err("Part21 exponent is outside i32"))?)}),_=>return Ok(None)}}let(Some(negative),Some(coefficient),Some(scale))=(negative,coefficient,scale)else{return Ok(None)};let coefficient=input_text(&mut fields[coefficient].1).expect("coefficient shape checked");Ok(Some(Part21Decimal{negative,coefficient,scale,exponent:exponent.flatten()}))}
fn whole(value:&mut DslValue)->Result<Option<V>,Fault>{let DslValue::Object(fields)=value else{return Ok(None)};if fields.len()>2{return Ok(None);}let tag=fields.iter().position(|(key,_)|key=="kind");let Some(tag)=tag else{return Ok(None)};let DslValue::String(kind)=&fields[tag].1 else{return Ok(None)};let kind=match kind.as_str(){"unset"=>0,"derived"=>1,"str"=>2,"enum"=>3,"binary"=>4,"int"=>5,"ref"=>6,"real"=>7,_=>return Ok(None)};if kind<2{return Ok((fields.len()==1).then_some(if kind==0{V::Unset}else{V::Derived}));}if fields.len()!=2{return Ok(None);}let payload=1-tag;if fields[payload].0!="value"{return Ok(None);}Ok(match kind{2=>input_text(&mut fields[payload].1).map(V::Str),3=>input_text(&mut fields[payload].1).map(V::Enum),4=>input_text(&mut fields[payload].1).map(V::Binary),5=>fields[payload].1.as_i64().map(V::Int),6=>fields[payload].1.as_u64().map(V::Ref),7=>decimal(&mut fields[payload].1)?.map(V::Real),_=>None})}
/// 🪡️ Transfer a scalar event's existing native owners; displaced text remains owned for funded close.
pub(super)fn apply(instance:&mut Part21Instance,event:&mut SnapshotEditEvent,retired:&mut Option<V>)->Result<bool,Fault>{let SnapshotEditEvent::SetValue{path,value}=event else{return Ok(false)};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return Ok(false);}let _row=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid own Part21 row"))?;if fields.next()!=Some("entities"){return Ok(false);}let part=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid own Part21 constituent"))?;if fields.next()!=Some("arguments"){return Ok(false);}let index=fields.next().and_then(|value|value.parse::<usize>().ok()).ok_or_else(||err("Invalid own Part21 argument"))?;let mut target=instance.entities.get_mut(part).and_then(|(_,args)|args.get_mut(index)).ok_or_else(||err("Own Part21 slot is missing"))?;let mut depth=0;loop{let Some(field)=fields.next()else{let Some(next)=whole(value)?else{return Ok(false)};*retired=Some(std::mem::replace(target,next));return Ok(true)};if field=="values"{if depth==128{return Err(err("Own Part21 edit depth exceeded"));}depth+=1;let Some(index)=fields.next().and_then(|value|value.parse::<usize>().ok())else{return Ok(false)};target=match target{V::List(items)|V::Typed{items,..}=>items.get_mut(index),_=>None}.ok_or_else(||err("Own Part21 child is missing"))?;continue;}
 if field=="typeName"&&fields.next().is_none(){let V::Typed{name,..}=target else{return Ok(false)};let Some(next)=input_text(value)else{return Ok(false)};*retired=Some(V::Str(std::mem::replace(name,next)));return Ok(true);}if field!="value"{return Ok(false);}let payload=fields.next();if let Some(payload)=payload{if fields.next().is_some(){return Ok(false);}let V::Real(number)=target else{return Ok(false)};match payload{"coefficient"=>{let Some(next)=input_text(value)else{return Ok(false)};*retired=Some(V::Str(std::mem::replace(&mut number.coefficient,next)));},"negative"=>{let Some(next)=value.as_bool()else{return Ok(false)};number.negative=next;},"scale"=>{let Some(next)=value.as_u64().and_then(|value|u32::try_from(value).ok())else{return Ok(false)};number.scale=next;},"exponent"=>{number.exponent=if matches!(value,DslValue::Null){None}else{Some(value.as_i64().and_then(|value|i32::try_from(value).ok()).ok_or_else(||err("Part21 exponent is outside i32"))?)};},_=>return Ok(false)}return Ok(true);}
 let replacement=match target{V::Str(_)=>input_text(value).map(V::Str),V::Enum(_)=>input_text(value).map(V::Enum),V::Binary(_)=>input_text(value).map(V::Binary),V::Int(_)=>value.as_i64().map(V::Int),V::Ref(_)=>value.as_u64().map(V::Ref),V::Real(_)=>decimal(value)?.map(V::Real),_=>None};let Some(replacement)=replacement else{return Ok(false)};*retired=Some(std::mem::replace(target,replacement));return Ok(true);
 }}

pub(super)fn row(event:&SnapshotEditEvent)->Option<usize>{let path=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::MoveValue{path,..}=>path,_=>return None};let mut fields=path.split('/').skip(1);if fields.next()!=Some("document")||fields.next()!=Some("instances"){return None;}let row=fields.next()?;if row.len()>20{return None;}row.parse::<usize>().ok()}
